-- Dashboard and planner hotspots: one function and two indexes.
-- Applied to the Neon database on 2026-10-06 (through the direct endpoint, not the pooler).
-- The server also creates all three at start-up (server/storage.js), so a fresh database
-- gets them without this file. Nothing here changes or deletes rows.

-- 1. The date a lead counts from on the dashboard. The body is generated by
--    leadCapturedAtSql() in server/dashboard.js; keep the two the same. If the expression
--    changes, rebuild the index: reindex index concurrently app_leads_captured_at_idx;
create or replace function kbc_lead_captured_at(lead_data jsonb, lead_created_at timestamptz)
returns timestamptz language sql immutable set timezone = 'UTC'
as $kbc$ select coalesce((case when nullif(((select min((case when nullif((item->>'captured_at')::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif((item->>'captured_at')::text, '')::timestamptz end)) from jsonb_array_elements(case when jsonb_typeof(coalesce(lead_data->'source_history', '[]'::jsonb)) = 'array' then coalesce(lead_data->'source_history', '[]'::jsonb) else '[]'::jsonb end) item))::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif(((select min((case when nullif((item->>'captured_at')::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif((item->>'captured_at')::text, '')::timestamptz end)) from jsonb_array_elements(case when jsonb_typeof(coalesce(lead_data->'source_history', '[]'::jsonb)) = 'array' then coalesce(lead_data->'source_history', '[]'::jsonb) else '[]'::jsonb end) item))::text, '')::timestamptz end), (case when nullif((lead_data->>'Created_Time')::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif((lead_data->>'Created_Time')::text, '')::timestamptz end), (case when nullif((lead_data->>'created_time')::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif((lead_data->>'created_time')::text, '')::timestamptz end), (case when nullif((lead_data->>'captured_at')::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif((lead_data->>'captured_at')::text, '')::timestamptz end), (case when nullif((lead_data->>'received_at')::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif((lead_data->>'received_at')::text, '')::timestamptz end), (case when nullif((lead_data->>'event_start_at')::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif((lead_data->>'event_start_at')::text, '')::timestamptz end), (case when nullif((lead_created_at)::text, '') ~ '^\d{4}-\d{2}-\d{2}' then nullif((lead_created_at)::text, '')::timestamptz end)) $kbc$;

-- 2. Lets a dashboard date range read only the leads inside it (was: every lead, about 1 s).
create index concurrently if not exists app_leads_captured_at_idx
  on app_leads (kbc_lead_captured_at(data, created_at));

-- 3. Order of the "all" and "done" task pages (was: full scan and an on-disk sort).
create index concurrently if not exists app_tasks_recent_idx
  on app_tasks ((coalesce(completed_at, due_at)) desc nulls last, id desc);

analyze app_leads;
analyze app_tasks;

